package com.example.starter.dr;

import org.springframework.http.HttpStatus;

/**
 * 需求响应业务异常：携带 HTTP 状态码与机器可读错误码。
 */
public class DrApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public DrApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public static DrApiException notFound(String message) {
        return new DrApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    public static DrApiException badRequest(String code, String message) {
        return new DrApiException(HttpStatus.BAD_REQUEST, code, message);
    }

    public static DrApiException conflict(String code, String message) {
        return new DrApiException(HttpStatus.CONFLICT, code, message);
    }

    public static DrApiException unprocessable(String code, String message) {
        return new DrApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }
}

package com.example.starter.dr.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 创建需求响应事件请求。时间统一使用 UTC（如 2026-09-23T01:00:00Z）。
 *
 * @param eventRef        事件业务编码，全局唯一
 * @param startUtc        事件起始时刻 UTC（含）
 * @param endUtc          事件结束时刻 UTC（不含），必须晚于起始时刻
 * @param intervalMinutes 固定区间粒度（分钟），区间长度必须为其整数倍
 */
public record EventCreateRequest(
        @NotBlank String eventRef,
        @NotNull Instant startUtc,
        @NotNull Instant endUtc,
        @NotNull Integer intervalMinutes) {
}

package com.example.starter.dr.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import java.math.BigDecimal;

/**
 * 登记参与电表请求。
 *
 * @param meterId         电表业务编码
 * @param committedValue  承诺单区间最大削减功率（kW，非负有限小数）
 * @param baselineVersion 登记时声明的基线版本标签
 */
public record EnrollRequest(
        @NotBlank String meterId,
        @NotNull @PositiveOrZero BigDecimal committedValue,
        @NotBlank String baselineVersion) {
}

package com.example.starter.dr.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import java.math.BigDecimal;

/**
 * 写入/更正单个曲线点请求。
 * 同一电表、区间、数据类型首次写入时 expectedVersion 为空（或为 0 语义等价：记录不得存在）；
 * 更正时必须显式携带当前版本号（前版本号）。
 *
 * @param dataType        数据类型：BASELINE=基线，ACTUAL=实测
 * @param intervalIdx     事件区间编号，从 0 开始
 * @param value           有限非负小数功率值（kW）
 * @param expectedVersion 期望的当前版本号；首次写入传 null，更正传前版本号
 */
public record PointWriteRequest(
        @NotBlank String dataType,
        @NotNull Integer intervalIdx,
        @NotNull @PositiveOrZero BigDecimal value,
        Integer expectedVersion) {
}

package com.example.starter.dr.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import java.util.List;

/**
 * 结算冻结请求。
 *
 * @param requestId       冻结请求幂等键：同键同参重放返回首次结果，同键异参返回 409
 * @param expectedVersion 调用方期望的事件聚合版本（登记电表次数对应版本），冲突返回 409
 * @param meters          每块电表逐区间的基线/实测证据版本
 */
public record FreezeRequest(
        @NotBlank String requestId,
        @NotNull @Positive Integer expectedVersion,
        @NotEmpty @Valid List<MeterEvidence> meters) {
}

package com.example.starter.dr.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.util.List;

/**
 * 冻结请求中单块电表的逐区间证据版本。
 *
 * @param meterId   电表业务编码
 * @param intervals 该电表每个区间对应的基线与实测版本号
 */
public record MeterEvidence(
        @NotBlank String meterId,
        @NotEmpty @Valid List<IntervalEvidence> intervals) {
}

package com.example.starter.dr.dto;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 单个区间的证据版本。
 *
 * @param intervalIdx     事件区间编号，从 0 开始
 * @param baselineVersion 该区间基线点当前必须持有的版本号
 * @param actualVersion   该区间实测点当前必须持有的版本号
 */
public record IntervalEvidence(
        @NotNull Integer intervalIdx,
        @NotNull @Positive Integer baselineVersion,
        @NotNull @Positive Integer actualVersion) {
}

