package com.example.starter.dr.dto;

import java.math.BigDecimal;

/**
 * 电表登记视图。
 *
 * @param id              登记记录 ID
 * @param meterId         电表业务编码
 * @param committedValue  承诺单区间最大交付量
 * @param baselineVersion 登记时声明的基线版本标签
 */
public record EnrollmentResponse(
        Long id,
        String meterId,
        BigDecimal committedValue,
        String baselineVersion) {
}

package com.example.starter.dr.dto;

import java.math.BigDecimal;

/**
 * 曲线点写入/更正结果。
 *
 * @param meterId     电表业务编码
 * @param dataType    数据类型：BASELINE/ACTUAL
 * @param intervalIdx 区间编号
 * @param value       当前数值（kW）
 * @param version     写入后的新版本号
 * @param corrected   true=更正既有版本，false=首次写入
 */
public record PointResponse(
        String meterId,
        String dataType,
        int intervalIdx,
        BigDecimal value,
        int version,
        boolean corrected) {
}

package com.example.starter.dr.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 冻结结算证据视图。
 *
 * @param freezeId        冻结头 ID
 * @param requestId       冻结请求幂等键
 * @param eventRef        事件业务编码
 * @param expectedVersion 冻结时的事件聚合版本
 * @param fingerprint     完整参数指纹
 * @param totalDelivered  总交付量
 * @param frozenAtUtc     冻结时刻 UTC
 * @param intervals       逐区间证据快照
 */
public record FreezeResponse(
        Long freezeId,
        String requestId,
        String eventRef,
        int expectedVersion,
        String fingerprint,
        BigDecimal totalDelivered,
        Instant frozenAtUtc,
        List<IntervalResult> intervals) {

    /**
     * 单个区间的冻结证据。
     */
    public record IntervalResult(
            String meterId,
            int intervalIdx,
            BigDecimal baselineValue,
            BigDecimal actualValue,
            int baselineVersion,
            int actualVersion,
            BigDecimal deliveredValue) {
    }
}

