 * 任何登记都先获取全表事件锁，再判断时间重叠，避免新电表无既有行可锁导致的漏判，
 * 也保证所有登记事务以相同顺序加锁、不会互锁。必须在事务内调用。
 */
public List<Long> lockAllEventRows() {
    return jdbc.queryForList("SELECT id FROM dr_event ORDER BY id FOR UPDATE", Long.class);
}

